window.AUTH=window.AUTH||{};window.AUTH["21-1086"]={"d":"21-1086","id":"2022/21-1086","n":"Allen v. Milligan","briefs":[{"k":"petitioner","label":"Brief of appellants/petitioners John H. Merrill, Alabama Secretary of State, et al.","date":"2022-04-25","url":"https://www.supremecourt.gov/DocketPDF/21/21-1086/221827/20220425152045101_Milligan%20-%20Merits%20Br%20FINAL%204-25.pdf","side":"pet","n":52},{"k":"respondent","label":"Brief of respondents Marcus Caster, et al.","date":"2022-07-11","url":"https://www.supremecourt.gov/DocketPDF/21/21-1086/229762/20220711135711406_2022-07-11%20Caster%20Merits%20Brief%20Final.pdf","side":"res","n":51},{"k":"respondent","label":"Brief of appellees Evan Milligan, et al.","date":"2022-07-11","url":"https://www.supremecourt.gov/DocketPDF/21/21-1086/229773/20220711132550198_2022.07.11%20Milligan%20Br.%20for%20Appellees_A.pdf","side":"res","n":65},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-07-18","url":"https://www.supremecourt.gov/DocketPDF/21/21-1086/230317/20220718201827432_21-1086bsacUnitedStates.pdf","side":"us","n":41},{"k":"reply","label":"Reply of appellants/petitioners John H. Merrill, Alabama Secretary of State, et al.","date":"2022-08-24","url":"https://www.supremecourt.gov/DocketPDF/21/21-1086/234404/20220824160744143_Merrill%20-%20Merits%20Reply%20Brief%20FINAL.pdf","side":"pet","n":49}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r33_dc8f.pdf","tr":true,"items":[{"t":"case","label":"Abbott v. Perez","cite":"138 S. Ct. 2305","y":2018,"id":"2017/17-586","sc":1,"by":{"0":"38, 42","1":"45","2":"25, 32, 48, 52","3":"13, 14, 17, 21","4":"24, 25"},"q":[{"src":"brief","b":2,"text":"there is a possibility of creating more than the existing number of reasonably compact [majority-minority] districts,","cite":"138 S. Ct. at 2331"}]},{"t":"case","label":"Abrams v. Johnson","cite":"521 U.S. 74","y":1997,"id":"1996/95-1425","sc":1,"by":{"0":"passim","2":"28, 56","4":"16"},"q":[{"src":"brief","b":0,"text":"a valid expression of legislative policy.","cite":"521 U.S. at 88"},{"src":"brief","b":0,"text":"inquiry should take into account ‘traditional districting principles such as maintaining communities of interest and traditional boundaries’","cite":"521 U.S. at 92"},{"src":"argument","who":"Mr. Lacour","text":"Vera, what Abrams, and what LULAC were all pushing towards when they said you must account for traditional districting principles. I don't know why you would even account for them except that if a plaintiff's failure to account for them in their map -- if -- if plaintiffs fail to account for them in their map, then their map can't really shed any light --"},{"src":"argument","who":"Mr. Lacour","text":"If you go back to Abrams, I mean, after Miller, with the max back -- max Black plan foisted upon Georgia in the -- after the 1990 census, it was sent back to the district court, who was forced to end up drawing a map for Georgia's 11 congressional districts."},{"src":"argument","who":"Mr. Lacour","text":"You know that you've maintained cores of your districts and that Supreme Court in Abrams even said that's fine as part of the -- the Gingles 1 analysis, but the district court said, well, here, it's not going to be the case."}]},{"t":"case","label":"Ala. Legis. Black Caucus v. Alabama","cite":"575 U.S. 254","y":2015,"id":"2014/13-895","sc":1,"by":{"0":"39","1":"54","2":"39, 42"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"are yet another installment in the `disastrous misadventure' of this Court's voting rights jurisprudence.","cite":"575 U. S. 254, 294"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"required States, including Alabama, to create supermajority-black voting districts or face denial Page Proof Pending Publication of preclearance.","cite":"575 U. S. 254, 298"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"much damage to the States' congressional and legislative district maps had already been done,","cite":"575 U. S., at 299"}]},{"t":"case","label":"Bartlett v. Strickland","cite":"556 U.S. 1","y":2009,"id":"2008/07-689","sc":1,"by":{"0":"passim","1":"passim","2":"27, 45, 46, 52","3":"12, 14, 15, 23, 28, 34","4":"passim"},"q":[{"src":"brief","b":2,"text":"help courts determine which claims could meet the totality-of-the-circumstances standard for a § 2 violation.","cite":"556 U.S. at 21"},{"src":"brief","b":2,"text":"[R]acial discrimination and racially polarized voting are not ancient history. Much remains to be done to ensure that citizens of all races have equal opportunity to share and participate in our democratic processes and traditions; and § 2 must be interpreted to ensure that continued progress.","cite":"556 U.S. at 25"},{"src":"brief","b":3,"text":"racial discrimination and racially polarized voting are not ancient history. Much remains to be done to ensure that citizens of all races have equal opportunity to share and participate in our democratic processes and traditions; and § 2 must be interpreted to ensure that continued progress.","cite":"556 U.S. at 25"},{"src":"brief","b":3,"text":"revise and reformulate the Gingles threshold inquiry that has been the baseline of [its] § 2 jurisprudence.","cite":"556 U.S. at 16"},{"src":"brief","b":4,"text":"avoid[] serious constitutional concerns under the Equal Protection Clause.","cite":"556 U.S. at 21"},{"src":"brief","b":4,"text":"[i]f §2 were interpreted to require crossover districts throughout the Nation, it would unnecessarily infuse race into virtually every redistricting, raising serious constitutional questions.","cite":"556 U.S. at 21"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`would unnecessarily infuse race into virtually every redistricting, raising serious constitutional questions.'","cite":"556 U. S., at 21"},{"src":"argument","who":"Mr. Ross","text":"That is because plaintiffs' maps show, consistent with Bartlett, that it is possible to draw maps that look very similar to Alabama's own Board of Education map and that increase opportunities for minority voters, while satisfying traditional and state redistricting criteria at least as well as Alabama's map."},{"src":"argument","who":"Mr. Ross","text":"Your Honor, I -- I'm not sure because this Court said in Bartlett that plaintiffs were required to draw an additional majority-minority district."},{"src":"argument","who":"Ms. Khanna","text":"And when this Court discussed the Gingles 1 standard in -- in Bartlett, it emphasized that the point of the Gingles 1 standard was to create an objective administrable rule not just for courts and litigants but also for states themselves."}]},{"t":"case","label":"Bethune-Hill v. Va. State Bd. of Elections","cite":"137 S. Ct. 788","y":2017,"id":"2016/15-680","sc":1,"by":{"0":"passim","1":"55","3":"25, 26","4":"13, 28"},"q":[{"src":"brief","b":0,"text":"could have drawn the same lines in accordance with traditional criteria.","cite":"137 S. Ct. at 798"},{"src":"brief","b":0,"text":"c[oming] into play only after the racebased decision had been made.","cite":"137 S. Ct. at 798"},{"src":"brief","b":4,"text":"necessary to depart from traditional principles","cite":"137 S. Ct. 788, 799"},{"src":"argument","who":"Mr. Lacour","text":"With -- with respect, first, again, I'm not sure why the Court has ever spoken about traditional districting principles and reasonable configuration, or at least the Court has never suggested that a map that the state could never enact itself under the Equal Protection Clause is somehow reasonably configured. If they came forward with a Cooper v. Harris map or the Bethune-Hill map --"},{"src":"argument","who":"Mr. Ross","text":"And so perhaps it would go to the fact that -- you know, that maybe you can't have a remedy that meets Gingles 1, but I would also say that you have the option of drawing a narrowly tailored district that -- where race may predominate, as this Court recognized in Bethune-Hill."},{"src":"argument","who":"General Prelogar","text":"And in the Bethune-Hill case, the Court specifically remanded a case where there had been a 55 percent target used for the district court to make a finding on predominance."}]},{"t":"case","label":"Brnovich v. Democratic Nat’l Comm.","cite":"141 S. Ct. 2321","y":2021,"id":"2020/19-1257","sc":1,"by":{"0":"passim","2":"34","3":"2, 3, 5, 11, 23, 31","4":"passim"},"q":[{"src":"brief","b":0,"text":"an end to the denial of the right to vote based on race.","cite":"141 S. Ct. 2321, 2330"},{"src":"brief","b":0,"text":"addressed the denial or abridgement of the right to vote in any part of the country.","cite":"141 S. Ct. at 2331"},{"src":"brief","b":2,"text":"focus on the issue of vote dilution.","cite":"141 S. Ct. at 2332"},{"src":"brief","b":2,"text":"does not demand proof of discriminatory purpose.","cite":"141 S. Ct. at 2341"},{"src":"brief","b":3,"text":"Despite the ratification of the Fifteenth Amendment, the right of African-Americans to vote was heavily suppressed for nearly a century.","cite":"141 S. Ct. 2321, 2330"},{"src":"brief","b":3,"text":"steady stream of § 2 vote-dilution cases,","cite":"141 S. Ct. at 2333"},{"src":"brief","b":4,"text":"does not deprive the States of their authority to establish nondiscriminatory voting rules.","cite":"141 S. Ct. at 2343"},{"src":"brief","b":4,"text":"neutral voting regulations with long pedigrees that are reasonable means of pursuing legitimate interests.","cite":"141 S. Ct. at 2341"},{"src":"argument","who":"Mr. Lacour","text":"Hall plurality and in Brnovich, benchmarks are critical in any Section 2 case. And we proposed a benchmark to the Court. Plaintiffs have not proposed any benchmark other than perhaps maximization or proportionality."},{"src":"argument","who":"Justice Kagan","text":"And then we said it recently as a year ago -- I dissented from this decision, but Brnovich says the fact that Section 2 does not demand proof of discriminatory purpose is one of the points of law that nobody disputes."},{"src":"argument","who":"Mr. Lacour","text":"If you look at the district court's opinion here, though -- and -- and one other thing I'd note, in Brnovich, when this Court emphasized that the legitimate state goals are critical at that totality of the circumstances stage."}]},{"t":"case","label":"Bush v. Vera","cite":"517 U.S. 952","y":1996,"id":"1995/94-805","sc":1,"by":{"0":"passim","1":"35","2":"27, 33, 51, 52, 53, 57","3":"17, 25, 26","4":"1, 16, 24"},"q":[{"src":"brief","b":0,"text":"district drawn in order to satisfy §2 must not subordinate traditional districting principles to race substantially more than is ‘reasonably necessary’ to avoid §2 liability.","cite":"517 U.S. 952, 979"},{"src":"brief","b":0,"text":"maintaining communities of interest and traditional boundaries.","cite":"517 U.S. at 977"},{"src":"brief","b":2,"text":"[a] § 2 district that is reasonably compact *** may pass strict scrutiny without having to defeat rival compact districts designed by [challengers or simulations] in endless ‘beauty contests.’","cite":"517 U.S. at 977"},{"src":"brief","b":2,"text":"not subordinate traditional districting principles to race substantially more than is ‘reasonably necessary’ to avoid § 2 liability.","cite":"517 U.S. at 979"},{"src":"brief","b":3,"text":"vote dilution as a consequence of racial bloc voting,","cite":"517 U.S. at 982"},{"src":"argument","who":"Mr. Lacour","text":"I think that's what Bush v. Vera, what Abrams, and what LULAC were all pushing towards when they said you must account for traditional districting principles."}]},{"t":"case","label":"City of Boerne v. Flores","cite":"521 U.S. 507","y":1997,"id":"1996/95-2074","sc":1,"by":{"0":"73, 75","1":"57, 59","2":"56, 57"},"q":[{"src":"brief","b":0,"text":"so out of proportion to a supposed remedial or preventive object that it cannot be understood as responsive to, or designed to prevent, unconstitutional behavior.","cite":"521 U.S. at 532"},{"src":"brief","b":1,"text":"[l]egislation which deters or remedies constitutional violations can fall within the sweep of Congress’ enforcement power,","cite":"521 U.S. at 518"},{"src":"brief","b":2,"text":"[l]egislation which deters or remedies constitutional violations *** even if in the process it prohibits conduct which is not itself unconstitutional[.]","cite":"521 U.S. 507, 518"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"Congress' parallel power to enforce the provisions of the Fifteenth Amendment.","cite":"521 U. S., at 518"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"the line between measures that remedy or prevent unconstitutional actions and measures that make a substantive change in the governing law.","cite":"521 U. S., at 519"}]},{"t":"case","label":"City of Mobile v. Bolden","cite":"446 U.S. 55","y":1980,"id":"1978/77-1844","sc":1,"by":{"0":"5, 6, 73, 74","1":"5, 44","2":"4","3":"2, 9, 20"},"q":[{"src":"brief","b":2,"text":"only if motivated by a discriminatory purpose.","cite":"446 U.S. 55, 60-62"},{"src":"argument","who":"Mr. Lacour","text":"They offer only one way to get that second majority-Black district: Split Mobile County and divide the Gulf by race. Their new versions of Districts 1 and 2 then stretch the width of the state to group together Black voters from disparate areas as far west as Mobile and as far east as the Georgia border."},{"src":"argument","who":"Mr. Lacour","text":"Justice White explained in his dissent in Mobile that they were requiring -- the plurality was requiring some sort of smoking gun proof identifying the exact official, and Justice White's position was no."},{"src":"argument","who":"Mr. Lacour","text":"First, on the segregation point, if -- if there really was that compact segregated part of Alabama to draw that second Black district, they wouldn't have had to have split Mobile for the first time ever, gone 170 miles northeast up to Montgomery, and then dipped a hundred miles to the southeast to Dothan, Alabama."}]},{"t":"case","label":"Cooper v. Harris","cite":"137 S. Ct. 1455","y":2017,"id":"2016/15-1262","sc":1,"by":{"0":"passim","1":"passim","2":"14, 28, 30, 52","3":"21, 25, 27, 33","4":"20, 24, 29"},"q":[{"src":"brief","b":0,"text":"is complying with operative provisions of the Voting Rights Act","cite":"137 S. Ct. 1455, 1464"},{"src":"brief","b":0,"text":"the State must establish that it had ‘good reasons’ to think it would transgress the Act if it did not draw race-based district lines.","cite":"137 S. Ct. at 1464"},{"src":"brief","b":1,"text":"no serious dispute that Black voters are ‘politically cohesive,’ nor that the challenged districts’ white majority votes ‘sufficiently as a bloc to usually defeat Black voters’ preferred candidate.’","cite":"137 S. Ct. 1455, 1470"},{"src":"brief","b":1,"text":"the minority group to elect its favored candidates.","cite":"137 S. Ct. at 1472"},{"src":"brief","b":2,"text":"usually ‘defeat the minority’s preferred candidate.’","cite":"137 S. Ct. 1455, 1470"},{"src":"brief","b":2,"text":"enjoy leeway to take race-based actions reasonably judged necessary under a proper interpretation of the VRA.","cite":"137 S. Ct. at 1472"},{"src":"brief","b":3,"text":"warrants significant deference on appeal to this Court.","cite":"137 S. Ct. at 1464"},{"src":"brief","b":3,"text":"in which members of the majority help a ‘large enough’ minority to elect its candidate of choice.","cite":"137 S. Ct. at 1470"}]},{"t":"case","label":"Davis v. Bandemer","cite":"478 U.S. 109","y":1986,"id":"1985/84-1244","sc":1,"by":{"0":"41, 64"}},{"t":"case","label":"Georgia v. Ashcroft","cite":"539 U.S. 461","y":2003,"id":"2002/02-182","sc":1,"by":{"0":"49, 69","1":"44","4":"4, 26"},"q":[{"src":"brief","b":0,"text":"discrimination in the exercise of the electoral franchise.","cite":"539 U.S. at 490"},{"src":"argument","who":"Mr. Lacour","text":"Their new versions of Districts 1 and 2 then stretch the width of the state to group together Black voters from disparate areas as far west as Mobile and as far east as the Georgia border."},{"src":"argument","who":"Mr. Lacour","text":"If you go back to Abrams, I mean, after Miller, with the max back -- max Black plan foisted upon Georgia in the -- after the 1990 census, it was sent back to the district court, who was forced to end up drawing a map for Georgia's 11 congressional districts."},{"src":"argument","who":"Mr. Lacour","text":"But, in Georgia, they indisputably did take into account preexisting cores. In Alabama, we indisputably do too. When the Democrats controlled the legislature in 2002 and Senator Hank Sanders from Selma, Alabama, proposed the 2002 map, it looked a lot like the 1992 map."}]},{"t":"case","label":"Gonzalez v. City of Aurora","cite":"535 F.3d 594","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/535/594/","by":{"0":"passim","3":"28, 29","4":"5, 30, 31, 32"},"q":[{"src":"brief","b":0,"text":"Court has found a problem under §2 all involve transparent gerrymandering that boosts one group’s chances at the expense of another’s","cite":"535 F.3d at 598"},{"src":"brief","b":0,"text":"outcome[s] of a race-neutral process in which all districts are compact,","cite":"535 F.3d at 598"},{"src":"brief","b":4,"text":"Section 2 requires an electoral process ‘equally open’ to all, not a process that favors one group over another.","cite":"535 F.3d 594, 598"}]},{"t":"case","label":"Growe v. Emison","cite":"507 U.S. 25","y":1993,"id":"1992/91-1420","sc":1,"by":{"0":"passim","1":"49, 51","2":"26, 27","3":"5, 12, 14, 30","4":"25"},"q":[{"src":"brief","b":0,"text":"there neither has been a wrong nor can be a remedy,","cite":"507 U.S. at 41"},{"src":"brief","b":1,"text":"submerg[ence] . . . in a larger white voting population","cite":"507 U.S. at 40"},{"src":"brief","b":2,"text":"the potential to elect a representative of [their] own choice in some [alternative] single-member district *** there neither has been a wrong nor can be a remedy.","cite":"507 U.S. 25, 40-41"},{"src":"brief","b":2,"text":"potential to elect a representative of its own choice","cite":"507 U.S. at 40"},{"src":"brief","b":3,"text":"[O]ther factors may also be relevant and may be considered.","cite":"507 U.S. 25"},{"src":"brief","b":3,"text":"showings are needed to establish that the minority [group] has the potential to elect a representative of its own choice in some singlemember district.","cite":"507 U.S. 25, 40"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"needed to establish that the minority has the potential to elect a representative of its own choice in some singlemember district.","cite":"507 U. S. 25, 40"}]},{"t":"case","label":"Harris v. McCrory","cite":"159 F. Supp. 3d 600","y":2016,"court":"M.D.N.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/159/600/","by":{"0":"68, 78"}},{"t":"case","label":"Holder v. Hall","cite":"512 U.S. 874","y":1994,"id":"1993/91-2012","sc":1,"by":{"0":"passim","1":"50, 51","3":"31"},"q":[{"src":"brief","b":0,"text":"a remedial provision directed specifically at eradicating discriminatory practices that restricted blacks’ ability to register and vote in the segregated South.","cite":"512 U.S. 874, 893"},{"src":"brief","b":0,"text":"a device for regulating, rationing, and apportioning political power among racial and ethnic groups.","cite":"512 U.S. at 893"},{"src":"brief","b":1,"text":"that Congress intended the 1982 amendment to cover [vote-dilution] claims","cite":"512 U.S. 874, 963"},{"src":"brief","b":1,"text":"Congress, which has ample power to amend the statute.","cite":"512 U.S. at 957"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"overruling the interpretation of § 2","cite":"512 U. S., at 944"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"the consciously segregated districting system currently being constructed in the name of the Voting Rights Act.","cite":"512 U. S., at 907"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"do not include a State's . . . choice of one districting scheme over another.","cite":"512 U. S., at 945"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"methodically carving the country into racially designated Page Proof Pending Publication electoral districts.","cite":"512 U. S., at 945"}]},{"t":"case","label":"Johnson v. De Grandy","cite":"512 U.S. 997","y":1994,"id":"1993/92-519","sc":1,"by":{"0":"passim","1":"passim","2":"29, 39, 40, 53","3":"14, 19, 21, 22","4":"passim"},"q":[{"src":"brief","b":0,"text":"promote and perpetuate efforts to devise majorityminority districts even in circumstances where they may not be necessary to achieve equal political and electoral opportunity.","cite":"512 U.S. at 1019"},{"src":"brief","b":0,"text":"‘proportionality … is obviously an indication that minority voters have equal opportunity, in spite of racial polarization, to participate in the political process and to elect representatives of their choice.’","cite":"512 U.S. at 1020"},{"src":"brief","b":1,"text":"reach[es] cases in which discriminatory intent is not identified.","cite":"512 U.S. 997, 1009 n.8"},{"src":"brief","b":1,"text":"mov[ing] from direct, over[t] impediments to the right to vote to more sophisticated devices that dilute minority voting strength.","cite":"512 U.S. at 1018"},{"src":"brief","b":2,"text":"minority members’ share of the relevant population.","cite":"512 U.S. at 1014 n.11"},{"src":"brief","b":2,"text":"the presence or absence of a violation be assessed ‘based on the totality of circumstances.’","cite":"512 U.S. at 1018"},{"src":"brief","b":3,"text":"an indication that minority voters have an equal opportunity, in spite of racial polarization, to participate in the political process and to elect representatives of their choice.","cite":"512 U.S. at 1020"},{"src":"brief","b":3,"text":"counter to the textual command of §2, that the presence or absence of a violation be assessed ‘based on the totality of circumstances,’","cite":"512 U.S. at 1018"},{"src":"argument","who":"Mr. Ross","text":"In De Grandy, this Court said --"},{"src":"argument","who":"Mr. Ross","text":"And just because you can draw an additional district doesn't mean that you would satisfy any of the other traditional -- or, excuse me, any of the other racial polarization, a totality of the circumstances, and that's why this Court in De Grandy added in proportionality as -- as a part of the totality so that it prevented maximization from being a -- a goal of Section 2."},{"src":"argument","who":"Mr. Lacour","text":"This Court didn't depart from Gingles and De Grandy when it recognized the importance of proportionality. You didn't depart from Gingles when you added traditional districting principles to the analysis when the Court started focusing on single-member districts."}]},{"t":"case","label":"Karcher v. Daggett","cite":"462 U.S. 725","y":1983,"id":"1982/81-2057","sc":1,"by":{"0":"61","4":"22"},"q":[{"src":"argument","who":"Mr. Lacour","text":"This Court in Karcher said that is a legitimate goal in redistricting. And the district court said: Well, you don't have to account for that traditional districting principle because that would make it really hard to satisfy Gingles."}]},{"t":"case","label":"Lawyer v. Dep’t of Justice","cite":"521 U.S. 567","y":1997,"id":"1996/95-2024","sc":1,"by":{"0":"43","2":"32, 44, 47"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"Congress' parallel power to enforce the provisions of the Fifteenth Amendment.","cite":"521 U. S., at 518"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"the line between measures that remedy or prevent unconstitutional actions and measures that make a substantive change in the governing law.","cite":"521 U. S., at 519"}]},{"t":"case","label":"League of United Latin Am. Citizens v. Perry","cite":"548 U.S. 399","y":2006,"id":"2005/05-204","sc":1,"by":{"0":"passim","1":"passim","3":"12, 14, 16, 17, 22","4":"passim"},"q":[{"src":"brief","b":1,"text":"the statutory text directs [courts] to consider the ‘totality of circumstances’ to determine whether members of a racial group have less opportunity than do other members of the electorate.","cite":"548 U.S. 399, 425–26"},{"src":"brief","b":3,"text":"could hardly be said to thwart minority voting power under § 2.","cite":"548 U.S. 399, 495"},{"src":"brief","b":4,"text":"traditional districting principles such as maintaining communities of interest and traditional boundaries,","cite":"548 U.S. 399, 433"}]},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"by":{"0":"72"}},{"t":"case","label":"Miller v. Johnson","cite":"515 U.S. 900","y":1995,"id":"1994/94-631","sc":1,"by":{"0":"passim","1":"26, 54, 55, 56","2":"45, 46","3":"25, 33","4":"passim"},"q":[{"src":"brief","b":0,"text":"compliance with federal antidiscrimination laws cannot justify race-based districting where the challenged district was not reasonably necessary under a constitutional reading and application of those laws.","cite":"515 U.S. 900, 921"},{"src":"brief","b":0,"text":"require States to create majority-minority districts wherever possible.","cite":"515 U.S. at 925"},{"src":"brief","b":1,"text":"the legislature subordinated traditional race-neutral districting principles.","cite":"515 U.S. at 916"},{"src":"brief","b":2,"text":"Redistricting legislatures will, for example, almost always be aware of racial demographics; but it does not follow that race predominates in the redistricting process.","cite":"515 U.S. 900, 916"},{"src":"brief","b":2,"text":"subordinate[s] traditional race-neutral districting principles *** to racial considerations.","cite":"515 U.S. at 916"},{"src":"brief","b":3,"text":"race for its own sake, and not other districting principles, was the legislature’s dominant and controlling rationale in drawing its district lines.","cite":"515 U.S. 900, 913"},{"src":"brief","b":3,"text":"the legislature’s dominant and controlling rationale in drawing its district lines.","cite":"515 U.S. at 913"},{"src":"brief","b":4,"text":"that States engage in presumptively unconstitutional race-based districting.","cite":"515 U.S. at 927"}]},{"t":"case","label":"Miss. Republican Exec. Comm. v. Brooks","cite":"469 U.S. 1002","y":1984,"url":"https://supreme.justia.com/cases/federal/us/469/1002/","sc":1,"by":{"0":"7, 33, 73","3":"32","4":"7"}},{"t":"case","label":"Montejo v. Louisiana","cite":"556 U.S. 778","y":2009,"id":"2008/07-1529","sc":1,"by":{"0":"52"}},{"t":"case","label":"Nw. Austin Mun. Util. Dist. No. One v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"by":{"0":"73, 75, 77"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"render[ing] the right to vote illusory for blacks,","cite":"557 U. S. 193, 220–221"}]},{"t":"case","label":"Ramos v. Louisiana","cite":"140 S. Ct. 1390","y":2020,"id":"2019/18-5924","sc":1,"by":{"0":"52","1":"43","2":"41, 42","3":"23"},"q":[{"src":"brief","b":1,"text":"the updating or correction of erroneous statutory precedents to the legislative process,","cite":"140 S. Ct. 1390, 1413"},{"src":"brief","b":2,"text":"find[] room in a crowded legislative docket","cite":"140 S. Ct. at 1413"}]},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"by":{"0":"50"}},{"t":"case","label":"Rucho v. Common Cause","cite":"139 S. Ct. 2484","y":2019,"id":"2018/18-422","sc":1,"by":{"0":"1, 79","3":"29","4":"19, 22"},"q":[{"src":"brief","b":4,"text":"meet[] the need for a limited and precise standard that is judicially discernible and manageable.","cite":"139 S. Ct. 2484, 2502"},{"src":"brief","b":4,"text":"Any judicial decision on what is ‘fair’ in this context would be an ‘unmoored determination’ of the sort characteristic of a political question beyond the competence of the federal courts.","cite":"139 S. Ct. at 2500"}]},{"t":"case","label":"Shaw v. Hunt","cite":"517 U.S. 907","y":1996,"id":"1995/94-923","sc":1,"by":{"0":"passim","1":"passim","3":"26, 27","4":"passim"},"q":[{"src":"brief","b":0,"text":"constitutional wrong occurs when race becomes the ‘dominant and controlling’ consideration","cite":"517 U.S. at 905"},{"src":"brief","b":0,"text":"came into play only after the race-based decision had been made.","cite":"517 U.S. at 907"},{"src":"brief","b":3,"text":"identify that discrimination, public or private, with some specificity before they may use raceconscious relief.","cite":"517 U.S. at 909"},{"src":"brief","b":4,"text":"While the States … may take remedial action when they possess evidence of past or present discrimination, they must identify that discrimination, public or private, with some specificity before they may use race-conscious relief.","cite":"517 U.S. at 909"},{"src":"brief","b":4,"text":"provide[] no guidance for a legislative body to determine the precise scope of the injury it seeks to remedy.","cite":"517 U.S. at 909"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`was the criterion that . . . could not be compromised,' and race-neutral considerations `came into play only after the race-based decision had been made'","cite":"517 U. S., at 907"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"because it provides no guidance for a legislative body to determine the precise scope of the injury it seeks to remedy.","cite":"517 U. S., at 909"}]},{"t":"case","label":"Shaw v. Reno","cite":"509 U.S. 630","y":1993,"id":"1992/92-357","sc":1,"by":{"0":"passim","1":"passim","2":"27, 35, 44, 50, 51, 52","3":"16, 25"},"q":[{"src":"brief","b":0,"text":"[c]lassifications of citizens solely on the basis of race ‘are by their very nature odious to a free people whose institutions are founded upon the doctrine of equality’","cite":"509 U.S. at 643"},{"src":"brief","b":0,"text":"Racial gerrymandering, even for remedial purposes, may balkanize us into competing racial factions; it threatens to carry us further from the goal of a political system in which race no longer matters—a goal that the Fourteenth and Fifteenth Amendments embody, and to which the Nation continues to aspire.","cite":"509 U.S. at 657"},{"src":"brief","b":1,"text":"[t]his Court never has held that race-conscious state decisionmaking is impermissible in all circumstances.","cite":"509 U.S. at 642"},{"src":"brief","b":1,"text":"share the same political interests, and will prefer the same candidates at the polls,","cite":"509 U.S. at 647"},{"src":"brief","b":2,"text":"may serve to defeat a claim that a district has been gerrymandered on racial lines.","cite":"509 U.S. 630, 646-647"},{"src":"brief","b":2,"text":"defeat a claim that a [state-enacted] district has been gerrymandered on racial lines.","cite":"509 U.S. at 647"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"race consciousness does not lead inevitably to impermissible race discrimination,","cite":"509 U. S., at 646"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"the goal of a political system in which race no longer matters,","cite":"509 U. S., at 657"}]},{"t":"case","label":"Shelby County v. Holder","cite":"570 U.S. 529","y":2013,"id":"2012/12-96","sc":1,"by":{"0":"73","1":"58","3":"32, 33","4":"41"},"q":[{"src":"brief","b":3,"text":"nationwide ban on racial discrimination in voting,","cite":"570 U.S. 529, 557"},{"src":"brief","b":4,"text":"But this case is about a part of the sentence that [Plaintiffs] do[] not emphasize— the part that asks whether a legislative means is ‘consist[ent] with the letter and spirit of the constitution.’","cite":"570 U.S. 529, 555"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`consist with the letter and spirit of the constitution.'","cite":"570 U. S. 529, 555"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`with the letter and spirit of the constitution.'","cite":"570 U. S., at 555"},{"src":"argument","who":"Justice Kagan","text":"Shelby County looks at Section 5 and it says no, Section 5, we don't need that anymore, and one of the things it says is we have Section 2."}]},{"t":"case","label":"Silver v. Diaz","cite":"522 U.S. 801","y":1997,"url":"https://supreme.justia.com/cases/federal/us/522/801/","sc":1,"by":{"0":"78"}},{"t":"case","label":"South Carolina v. Katzenbach","cite":"383 U.S. 301","y":1966,"id":"1965/22_orig","sc":1,"by":{"0":"72, 74","1":"4, 58","2":"4, 56","4":"41"},"q":[{"src":"brief","b":1,"text":"unremitting and ingenious defiance of the Constitution","cite":"383 U.S. 301, 309"},{"src":"brief","b":2,"text":"rid the country of racial discrimination in voting.","cite":"383 U.S. 301, 315"},{"src":"brief","b":4,"text":"Congress may enforce the Fifteenth Amendment by legislation that extends beyond the Amendment’s text so long as the ‘end [is] legitimate’ and the ‘means … are appropriate.’","cite":"383 U.S. 301, 326"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"banish the blight of racial discrimination in voting.","cite":"383 U. S., at 308"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"with a long history as a `notorious means to deny and abridge voting rights on racial grounds.'","cite":"383 U. S. 301, 355"},{"src":"argument","who":"Justice Alito","text":"As -- as a practical matter, in every place in the South, and maybe in other places, if the first Gingles factor, first Gingles condition, can be satisfied, will not the plaintiffs always run the table?"}]},{"t":"case","label":"Thornburg v. Gingles","cite":"478 U.S. 30","y":1986,"id":"1985/83-1968","sc":1,"by":{"0":"passim","1":"passim","2":"55","3":"passim","4":"passim"},"q":[{"src":"brief","b":0,"text":"the extent to which members of the minority group in the state or political subdivision bear the effects of discrimination in such areas as education, employment and health, which hinder their ability to participate effectively in the political process.","cite":"478 U.S. at 37"},{"src":"brief","b":1,"text":"also to deal with the accumulation of discrimination.","cite":"478 U.S. at 44 n.9"},{"src":"brief","b":1,"text":"substantially revise[] §2 to make clear that a violation could be proved by showing discriminatory effect alone.","cite":"478 U.S. at 35"},{"src":"brief","b":2,"text":"the political processes *** not [being] equally open","cite":"478 U.S. at 98"},{"src":"brief","b":2,"text":"generally minimize or cancel, black voters’ ability to elect representatives of their choice","cite":"478 U.S. at 56, 57"},{"src":"brief","b":3,"text":"less opportunity than white voters to elect representatives of their choice.","cite":"478 U.S. at 80"},{"src":"brief","b":3,"text":"does not assume the existence of racial bloc voting; plaintiffs must prove it.","cite":"478 U.S. at 46"},{"src":"brief","b":4,"text":"might be probative of a §2 violation,","cite":"478 U.S. 30, 36"}]},{"t":"case","label":"United States v. Wong Kim Ark","cite":"169 U.S. 649","y":1898,"id":"1850-1900/169us649","sc":1,"by":{"0":"78"}},{"t":"case","label":"Vieth v. Jubelirer","cite":"541 U.S. 267","y":2004,"id":"2003/02-1580","sc":1,"by":{"0":"40, 69","4":"18"},"q":[{"src":"brief","b":0,"text":"that judicial action must be governed by standard, by rule.","cite":"541 U.S. at 278"},{"src":"brief","b":0,"text":"long record of puzzlement and consternation,","cite":"541 U.S. at 283"}]},{"t":"case","label":"Voinovich v. Quilter","cite":"507 U.S. 146","y":1993,"id":"1992/91-1618","sc":1,"by":{"0":"9, 36, 43, 52","1":"passim","2":"27","3":"14, 30","4":"13, 15, 25"},"q":[{"src":"brief","b":0,"text":"§2 simply does not speak to the matter,","cite":"507 U.S. at 155"},{"src":"brief","b":1,"text":"fragmented minority group will be unable to muster sufficient votes in any district to carry its candidate to victory.","cite":"507 U.S. 146, 153"},{"src":"brief","b":1,"text":"‘interact[ing] with social and historical conditions,’ impairs the ability of a protected class to elect its candidate of choice on an equal basis with other voters","cite":"507 U.S. at 153"},{"src":"brief","b":2,"text":"racial minority group voting strength *** by the dispersal of blacks into districts in which they constitute an ineffective minority of voters.","cite":"507 U.S. 146, 154"},{"src":"brief","b":4,"text":"the Gingles factors cannot be applied mechanically and without regard to the nature of the claim.","cite":"507 U.S. at 158"}]},{"t":"case","label":"Wesch v. Hunt","cite":"785 F. Supp. 1491","y":1992,"court":"S.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp./785/1491/","by":{"0":"11","1":"15","2":"9","4":"32"},"q":[{"src":"brief","b":2,"text":"on the part of state political leadership to limit black voting potential ***.","cite":"785 F. Supp. at 1496"}]},{"t":"case","label":"Whitcomb v. Chavis","cite":"403 U.S. 124","y":1971,"id":"1970/92","sc":1,"by":{"0":"5","2":"25","3":"11","4":"7"},"q":[{"src":"argument","who":"Mr. Lacour","text":"What we have laid out in the brief is what we think the best reading of the text, which, when the Court -- when Congress decided to put in 2(b), that language from Whitcomb and from White v."},{"src":"argument","who":"Mr. Lacour","text":"Well, if you look back at White and if you look back at Whitcomb, they say invidious discrimination half a dozen times. Justice White explained in his dissent in Mobile that they were requiring -- the plurality was requiring some sort of smoking gun proof identifying the exact official, and Justice White's position was no."}]},{"t":"case","label":"White v. Regester","cite":"412 U.S. 755","y":1973,"id":"1972/72-147","sc":1,"by":{"0":"passim","1":"passim","2":"4, 25, 28","3":"3, 11, 30","4":"7, 11"},"q":[{"src":"brief","b":0,"text":"‘produce[d] evidence to support findings that the political processes leading to nomination and election were not equally open’","cite":"412 U.S. at 766"},{"src":"brief","b":1,"text":"participate in the political processes and to elect legislators of their choice.","cite":"412 U.S. at 766"},{"src":"brief","b":2,"text":"invidiously *** cancel out or minimize the voting strength of racial groups,","cite":"412 U.S. 755, 765"},{"src":"brief","b":2,"text":"less opportunity than did other[s] *** to elect legislators of their choice.","cite":"412 U.S. at 766, 769"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"in the light of past and present reality, political and otherwise.","cite":"412 U. S., at 767, 770"},{"src":"argument","who":"Mr. Lacour","text":"What we have laid out in the brief is what we think the best reading of the text, which, when the Court -- when Congress decided to put in 2(b), that language from Whitcomb and from White v. Regester, they were importing an invidious discrimination test."},{"src":"argument","who":"Mr. Lacour","text":"Regester what the Senate fact -- what the Senate report referred to as the White Results Test. Well, if you look back at White and if you look back at Whitcomb, they say invidious discrimination half a dozen times."}]},{"t":"case","label":"White v. Weiser","cite":"412 U.S. 783","y":1973,"id":"1972/71-1623","sc":1,"by":{"0":"61"},"q":[{"src":"brief","b":0,"text":"‘produce[d] evidence to support findings that the political processes leading to nomination and election were not equally open’","cite":"412 U.S. at 766"},{"src":"brief","b":0,"text":"the policies and preferences of the State.","cite":"412 U.S. 783, 795"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"in the light of past and present reality, political and otherwise.","cite":"412 U. S., at 767, 770"}]},{"t":"case","label":"Wis. Legislature v. Wis. Elections Comm’n","cite":"142 S. Ct. 1245","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./142/1245/","sc":1,"by":{"0":"passim","1":"7, 49","3":"passim","4":"passim"},"q":[{"src":"brief","b":0,"text":"satisfying the Gingles preconditions is necessary but not sufficient to show a §2 violation.","cite":"142 S. Ct. at 1248"},{"src":"brief","b":0,"text":"prove[] that its race-based sorting of voters is narrowly tailored to comply with the VRA.","cite":"142 S. Ct. at 1248"},{"src":"brief","b":3,"text":"a majority group must vote sufficiently as a bloc to enable it to usually defeat the minority group’s preferred candidate,","cite":"142 S. Ct. at 1248"},{"src":"brief","b":3,"text":"den[ied] black voters equal political opportunity.","cite":"142 S. Ct. at 1250"},{"src":"brief","b":4,"text":"den[ies] black voters equal political opportunity.","cite":"142 S. Ct. at 1250"},{"src":"brief","b":4,"text":"sufficiently large and compact to constitute a majority in a reasonably configured district.","cite":"142 S. Ct. at 1248"}]},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"0":"3","1":"57"}},{"t":"const","label":"Amendment XV","clauses":[["fifteenth-amendment","Fifteenth Amendment"]],"text":"The right of citizens of the United States to vote shall not be denied or abridged by the United States or by any State on account of race, color, or previous condition of servitude-- The Congress shall have power to enforce this article by appropriate legislation.","by":{"0":"passim","1":"57, 59","2":"56","3":"2, 32, 33"}},{"t":"usc","label":"28 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/28/1253","by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 2284","url":"https://www.law.cornell.edu/uscode/text/28/2284","subs":["(a)"],"stext":{"head":"§2284. Three-judge court; when required; composition; procedure","paras":[[0,"(a) A district court of three judges shall be convened when otherwise required by Act of Congress, or when an action is filed challenging the constitutionality of the apportionment of congressional districts or the apportionment of any statewide legislative body."],[0,"(b) In any action required to be heard and determined by a district court of three judges under subsection (a) of this section, the composition and procedure of the court shall be as follows:"],[0,"(1) Upon the filing of a request for three judges, the judge to whom the request is presented shall, unless he determines that three judges are not required, immediately notify the chief judge of the circuit, who shall designate two other judges, at least one of whom shall be a circuit judge. The judges so designated, and the judge to whom the request was presented, shall serve as members of the court to hear and determine the action or proceeding."],[0,"(2) If the action is against a State, or officer or agency thereof, at least five days' notice of hearing of the action shall be given by registered or certified mail to the Governor and attorney general of the State."],[0,"(3) A single judge may conduct all proceedings except the trial, and enter all orders permitted by the rules of civil procedure except as provided in this subsection. He may grant a temporary restraining order on a specific finding, based on evidence submitted, that specified irreparable damage will result if the order is not granted, which order, unless previously revoked by the district judge, shall remain in force only until the hearing and determination by the district court of three judges of an application for a preliminary injunction. A single judge shall not appoint a master, or order a reference, or hear and determine any application for a preliminary or permanent injunction or motion to vacate such an injunction, or enter judgment on the merits. Any action of a single judge may be reviewed by the full court at any time before final judgment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2284?type=usc&year=mostrecent&link-type=html"},"by":{"0":"19","3":"6"}},{"t":"usc","label":"52 U.S.C. § 10301","url":"https://www.law.cornell.edu/uscode/text/52/10301","subs":["(a)","(b)"],"stext":{"head":"§10301. Denial or abridgement of right to vote on account of race or color through voting qualifications or prerequisites; establishment of violation","paras":[[0,"(a) No voting qualification or prerequisite to voting or standard, practice, or procedure shall be imposed or applied by any State or political subdivision in a manner which results in a denial or abridgement of the right of any citizen of the United States to vote on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, as provided in subsection (b)."],[0,"(b) A violation of subsection (a) is established if, based on the totality of circumstances, it is shown that the political processes leading to nomination or election in the State or political subdivision are not equally open to participation by members of a class of citizens protected by subsection (a) in that its members have less opportunity than other members of the electorate to participate in the political process and to elect representatives of their choice. The extent to which members of a protected class have been elected to office in the State or political subdivision is one circumstance which may be considered: Provided, That nothing in this section establishes a right to have members of a protected class elected in numbers equal to their proportion in the population."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10301?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, passim, passim","1":"passim","2":"23, 43, 54, 5, 54, 55, 1, 5, 20, 25, 26, 28, 40, 54","3":"1, 30, 30","4":"passim, passim"},"q":[{"src":"brief","b":0,"text":"have less opportunity than other members of the electorate to participate in the political process and to elect representatives of their choice.","cite":"52 U.S.C. §10301(b)"},{"src":"brief","b":0,"text":"have less opportunity than other members … to participate in the political process and to elect representatives of their choice.","cite":"52 U.S.C. §10301(b)"},{"src":"brief","b":1,"text":"results in a denial or abridgement of the right of any citizen of the United States to vote on account of race or color.","cite":"52 U.S.C. §10301(a)"},{"src":"brief","b":1,"text":"in that its members have less opportunity than other members of the electorate to participate in the political process and to elect representatives of their choice.","cite":"52 U.S.C. §10301(b)"},{"src":"brief","b":2,"text":"voting qualification or prerequisite to voting or standard, practice, or procedure *** which results in a denial or abridgement of the right of any citizen of the United States to vote on account of race.","cite":"52 U.S.C. § 10301(a)"},{"src":"brief","b":2,"text":"have less opportunity *** to elect representatives of their choice.","cite":"52 U.S.C. § 10301(b)"},{"src":"brief","b":3,"text":"in that its members have less opportunity than other members of the electorate to participate in the political process and to elect representatives of their choice.","cite":"52 U.S.C. 10301(b)"},{"src":"brief","b":3,"text":"establish[] a right to have members of a protected class elected in numbers equal to their proportion in the population.","cite":"52 U.S.C. 10301(b)"}]},{"t":"law","label":"Pub. L. No. 89-110","url":"https://www.govinfo.gov/link/statute/79/437","by":{"0":"32, 33"}},{"t":"law","label":"Pub. L. No. 97-205","url":"https://www.govinfo.gov/link/statute/96/134","by":{"0":"33"}},{"t":"case","label":"Ala. Legis. Black Caucus v. Alabama","cite":"231 F. Supp. 3d 1026","y":2017,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/231/1026/","by":{"1":"12","2":"6, 7","4":"33"},"q":[{"src":"brief","b":2,"text":"very uncommon in the First World.","cite":"231 F. Supp. 3d at 1033"}]},{"t":"case","label":"Allen v. City of Evergreen","cite":"2014 WL 12607819","y":2014,"court":"S.D. Ala. Jan. 13","by":{"1":"12"}},{"t":"case","label":"Anderson v. City of Bessemer","cite":"470 U.S. 564","y":1985,"id":"1984/83-1623","sc":1,"by":{"1":"29, 30","2":"36, 37"},"q":[{"src":"brief","b":1,"text":"is left with the definite and firm conviction that a mistake has been committed.","cite":"470 U.S. 564, 573"},{"src":"brief","b":2,"text":"can virtually never be clear error","cite":"470 U.S. 564, 376"}]},{"t":"case","label":"Ankenbrandt v. Richards","cite":"504 U.S. 689","y":1992,"id":"1991/91-367","sc":1,"by":{"1":"44"}},{"t":"case","label":"Camp v. Wesch","cite":"504 U.S. 902","y":1992,"url":"https://supreme.justia.com/cases/federal/us/504/902/","sc":1,"by":{"1":"15"}},{"t":"case","label":"Chen v. City of Houston","cite":"206 F.3d 502","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/206/502/","by":{"1":"37"},"q":[{"src":"brief","b":1,"text":"there is more than one way to draw a district so that it can reasonably be described as meaningfully adhering to traditional principles.","cite":"206 F.3d 502, 519"},{"src":"argument","who":"Justice Sotomayor","text":"I read Amici Chen's brief, and he says that there's only been 31 vote dilution cases that resulted in merits decision over the last two redistricting cycles, that's out of 435 plans, and that only eight were successful."},{"src":"argument","who":"Ms. Khanna","text":"I believe that the -- the amicus brief from Professors Chen and Stephanopoulos talks about various studies that have been done that would show that if we were to apply these -- these race-blind simulations, they would obliterate a number of majority-minority districts."}]},{"t":"case","label":"Chisom v. Roemer","cite":"501 U.S. 380","y":1991,"id":"1990/90-757","sc":1,"by":{"1":"4, 50, 51","2":"25","3":"3"},"q":[{"src":"brief","b":1,"text":"rid[ding] the country of racial discrimination in voting.","cite":"501 U.S. 380, 403"},{"src":"brief","b":1,"text":"minimize a racial minority’s ability to influence the outcome of an election,","cite":"501 U.S. at 390"},{"src":"brief","b":2,"text":"patterned after the language used *** in White v. Regester, 412 U.S. 755 (1973), and Whitcomb v. Chavis, 403 U. S. 124 (1971)","cite":"501 U.S. 380, 398"},{"src":"brief","b":3,"text":"[u]nder the amended statute, proof of intent is no longer required.","cite":"501 U.S. 380, 394"},{"src":"argument","who":"Justice Kagan","text":"And then we said it in Chisom. And then we said it recently as a year ago -- I dissented from this decision, but Brnovich says the fact that Section 2 does not demand proof of discriminatory purpose is one of the points of law that nobody disputes."}]},{"t":"case","label":"City of Cleburne v. Cleburne Living Ctr., Inc.","cite":"473 U.S. 432","y":1985,"id":"1984/84-468","sc":1,"by":{"1":"59"}},{"t":"case","label":"City of Rome v. United States","cite":"446 U.S. 156","y":1980,"id":"1979/78-1840","sc":1,"by":{"1":"57, 58","3":"32"},"q":[{"src":"brief","b":1,"text":"foreclose any argument that Congress may not, pursuant to [the Fifteenth Amendment], outlaw voting practices that are discriminatory in effect.","cite":"446 U.S. 156, 173"},{"src":"brief","b":3,"text":"outlaw voting practices that are discriminatory in effect.","cite":"446 U.S. 156, 173"}]},{"t":"case","label":"Davis v. Chiles","cite":"139 F.3d 1414","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/139/1414/","by":{"1":"31, 33, 34"},"q":[{"src":"brief","b":1,"text":"impossible, as a matter of law, for any plaintiff to bring a successful Section Two action,","cite":"139 F.3d at 1425"}]},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"by":{"1":"43","2":"41","3":"23"}},{"t":"case","label":"Jones v. Jefferson Cnty. Bd. of Educ.","cite":"2019 WL 7500528","y":2019,"court":"N.D. Ala. Dec. 16","by":{"1":"12"}},{"t":"case","label":"Kimble v. Marvel Ent., LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"by":{"1":"passim","2":"21, 41, 42"},"q":[{"src":"brief","b":1,"text":"can correct any mistake it sees,","cite":"576 U.S. at 456"},{"src":"brief","b":2,"text":"Congress can correct any mistake it sees.","cite":"576 U.S. at 456"}]},{"t":"case","label":"Merrill v. Milligan","cite":"142 S. Ct. 879","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./142/879/","sc":1,"by":{"1":"22","2":"19","4":"24"},"q":[{"src":"brief","b":4,"text":"Court’s case law in this area is notoriously unclear and confusing.","cite":"142 S. Ct. 879, 881"},{"src":"argument","who":"Chief Justice Roberts","text":"We'll hear argument first this morning in Case 21-1086, Merrill versus Milligan, and the consolidated case. Mr. LaCour. ORAL ARGUMENT OF EDMUND G."}]},{"t":"case","label":"Nipper v. Smith","cite":"39 F.3d 1494","y":1994,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/39/1494/","by":{"1":"60"},"q":[{"src":"brief","b":1,"text":"The presence or absence of each [Gingles and Senate] factor therefore serves as a piece of evidence pointing either towards or away from an ultimate conclusion that an electoral system is or is not operating to dilute a minority group’s voting strength on account of race.","cite":"39 F.3d 1494, 1526"}]},{"t":"case","label":"North Carolina v. Covington","cite":"138 S. Ct. 2548","y":2018,"id":"2017/17-1364","sc":1,"by":{"1":"54","2":"30"},"q":[{"src":"brief","b":1,"text":"does not amount to a warrant for ‘racial quotas.’","cite":"138 S. Ct. 2548, 2554"},{"src":"brief","b":2,"text":"this Court has long recognized the distinction between being aware of racial considerations and being motivated by them.","cite":"138 S. Ct. at 2554"}]},{"t":"case","label":"Oregon v. Mitchell","cite":"400 U.S. 112","y":1970,"id":"1970/43-orig","sc":1,"by":{"1":"57"}},{"t":"case","label":"Reno v. Bossier Par. Sch. Bd.","cite":"528 U.S. 320","y":2000,"id":"1998/98-405","sc":1,"by":{"1":"44, 50","2":"35, 43, 55","4":"13, 14"},"q":[{"src":"brief","b":2,"text":"retrogression is not the inquiry in § 2 dilution cases.","cite":"528 U.S. 320, 334"},{"src":"brief","b":4,"text":"a race conscious ‘comparison’ between minorities’ relative opportunities under ‘the status quo’ and ‘a hypothetical alternative.’","cite":"528 U.S. 320, 334"}]},{"t":"case","label":"Robinson v. Ardoin","cite":"37 F.4th 208","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/37/208/","by":{"1":"31, 34, 37","2":"44","3":"27, 34"},"q":[{"src":"brief","b":3,"text":"[i]llustrative maps are just that— illustrative.","cite":"37 F.4th 208, 223"}]},{"t":"case","label":"Rogers v. Lodge","cite":"458 U.S. 613","y":1982,"id":"1981/80-2100","sc":1,"by":{"1":"28, 59","2":"20, 29, 57"},"q":[{"src":"brief","b":1,"text":"bear[s] heavily on the issue of purposeful discrimination.","cite":"458 U.S. at 623"},{"src":"brief","b":2,"text":"relevant to the issue of intentional discrimination,","cite":"458 U.S. 613, 623-624"},{"src":"argument","who":"Mr. Lacour","text":"-- in Rogers v. Lodge."}]},{"t":"case","label":"Shelley v. Kraemer","cite":"334 U.S. 1","y":1948,"id":"1940-1955/334us1","sc":1,"by":{"1":"53"}},{"t":"case","label":"Stout ex rel. Stout v. Jefferson Cnty. Bd. of Educ.","cite":"882 F.3d 988","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/882/988/","by":{"1":"12"}},{"t":"case","label":"United States v. McGregor","cite":"824 F. Supp. 2d 1339","y":2011,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/824/1339/","by":{"1":"1, 10, 12","2":"7, 38","4":"34"},"q":[{"src":"brief","b":1,"text":"remain[s] regrettably entrenched in the high echelons of state government.","cite":"824 F. Supp. 2d 1339, 1347"},{"src":"brief","b":2,"text":"racist sentiments *** remain regrettably entrenched in the high echelons of [Alabama] government.","cite":"824 F. Supp. 2d at 1347"},{"src":"brief","b":4,"text":"‘unremitting and ingenious defiance of the Constitution’ to exclude Black Americans.","cite":"824 F. Supp. 2d 1339"}]},{"t":"law","label":"Pub. L. No. 109-246","url":"https://www.govinfo.gov/link/plaw/109/public/246","by":{"1":"44","2":"42"}},{"t":"case","label":"Allen v. State Bd. of Elections","cite":"393 U.S. 544","y":1969,"id":"1968/3","sc":1,"by":{"2":"4"},"q":[{"src":"brief","b":2,"text":"a dilution of [minority] voting power.","cite":"393 U.S. 544, 565-566, 569"}]},{"t":"case","label":"Barnett v. City of Chicago","cite":"141 F.3d 699","court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/141/699/","by":{"2":"45"},"q":[{"src":"brief","b":2,"text":"[T]he fine-tuning of the [illustrative plan] can be left to the remedial stage of the litigation.","cite":"141 F.3d 699, 702"}]},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"by":{"2":"44"}},{"t":"case","label":"Burton v. Hobbie","cite":"561 F. Supp. 1029","y":1983,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp./561/1029/","by":{"2":"7","4":"33"},"q":[{"src":"brief","b":4,"text":"provid[ing] an apportionment plan that is fair to all the people of Alabama.","cite":"561 F. Supp. 1029, 1030"}]},{"t":"case","label":"Busbee v. Smith","cite":"549 F. Supp. 494","y":1982,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./549/494/","by":{"2":"39"}},{"t":"case","label":"Clark v. Calhoun Cnty.","cite":"88 F.3d 1393","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/88/1393/","by":{"2":"43"}},{"t":"case","label":"Cottier v. City of Martin","cite":"604 F.3d 553","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/604/553/","by":{"2":"28"}},{"t":"case","label":"Easley v. Cromartie","cite":"532 U.S. 234","y":2001,"id":"2000/99-1864","sc":1,"by":{"2":"45"},"q":[{"src":"brief","b":2,"text":"[s]trict scrutiny does not apply merely because redistricting is performed with consciousness of race.","cite":"532 U.S. 234, 253-254"}]},{"t":"case","label":"Flowers v. Mississippi","cite":"139 S. Ct. 2228","y":2019,"id":"2018/17-9572","sc":1,"by":{"2":"29, 38"}},{"t":"case","label":"Fusilier v. Landry","cite":"963 F.3d 447","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/963/447/","by":{"2":"30"}},{"t":"case","label":"FW/PBS, Inc. v. Dallas","cite":"493 U.S. 215","y":1990,"id":"1989/87-2012","sc":1,"by":{"2":"48"}},{"t":"case","label":"Gomillion v. Lightfoot","cite":"364 U.S. 339","y":1960,"id":"1960/32","sc":1,"by":{"2":"4, 53"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"by":{"2":"42"}},{"t":"case","label":"Johnson v. Hamrick","cite":"296 F.3d 1065","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/296/1065/","by":{"2":"28"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"by":{"2":"55"},"q":[{"src":"brief","b":2,"text":"Congress use[s] the materially same language [in later enactments], it presumptively [is] aware of the longstanding judicial interpretation of the phrase and intend[s] for it to retain its established meaning.","cite":"138 S. Ct. 1752, 1762"}]},{"t":"case","label":"NAACP v. Fordice","cite":"252 F.3d 361","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/361/","by":{"2":"30"}},{"t":"case","label":"Nev. Dep’t of Hum. Res. v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"had evidence of a pattern of constitutional violations.","cite":"538 U.S. 721, 727-729"}]},{"t":"case","label":"Reno v. Bossier Par. Sch. Bd.","cite":"520 U.S. 471","y":1997,"id":"1996/95-1455","sc":1,"by":{"2":"26"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"the very concept of vote dilution implies—and, indeed, necessitates—the existence of an `undiluted' practice against which the fact of dilution may be measured.","cite":"520 U. S. 471, 480"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"a violation of § 2 is no longer a fortiori a violation of","cite":"520 U. S., at 482"}]},{"t":"case","label":"Shepard v. United States","cite":"544 U.S. 13","y":2005,"id":"2004/03-9168","sc":1,"by":{"2":"42"},"q":[{"src":"brief","b":2,"text":"enhance[s] even the usual precedential force","cite":"544 U.S. 13, 23"}]},{"t":"case","label":"Sims v. Amos","cite":"336 F. Supp. 924","y":1972,"url":"https://www.courtlistener.com/c/F.%20Supp./336/924/","by":{"2":"7"}},{"t":"case","label":"Sims v. Baggett","cite":"247 F. Supp. 96","y":1965,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp./247/96/","by":{"2":"7"}},{"t":"case","label":"Stabler v. Thurston Cnty","cite":"129 F.3d 105","y":1997,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/129/105/","by":{"2":"27"}},{"t":"case","label":"United States v. Hays","cite":"515 U.S. 737","y":1995,"id":"1994/94-558","sc":1,"by":{"2":"46, 47"},"q":[{"src":"brief","b":2,"text":"does not lead inevitably to impermissible race discrimination.","cite":"515 U.S. 737, 745-746"}]},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"by":{"2":"22, 44"}},{"t":"case","label":"Veasey v. Abbott","cite":"830 F.3d 216","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/830/216/","by":{"2":"55"}},{"t":"case","label":"Village of Arlington Heights v. Metro. Hous. Dev. Corp.","cite":"429 U.S. 252","y":1977,"id":"1976/75-616","sc":1,"by":{"2":"29"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"does not require a plaintiff to prove that the challenged action rested solely on racially discriminatory purpose[ ].","cite":"429 U. S. 252, 265"}]},{"t":"usc","label":"52 U.S.C. § 10101","url":"https://www.law.cornell.edu/uscode/text/52/10101","subs":["(e)"],"stext":{"head":"§10101. Voting rights","paras":[[0,"(a) Race, color, or previous condition not to affect right to vote; uniform standards for voting qualifications; errors or omissions from papers; literacy tests; agreements between Attorney General and State or local authorities; definitions"],[0,"(1) All citizens of the United States who are otherwise qualified by law to vote at any election by the people in any State, Territory, district, county, city, parish, township, school district, municipality, or other territorial subdivision, shall be entitled and allowed to vote at all such elections, without distinction of race, color, or previous condition of servitude; any constitution, law, custom, usage, or regulation of any State or Territory, or by or under its authority, to the contrary notwithstanding."],[0,"(2) No person acting under color of law shall—"],[1,"(A) in determining whether any individual is qualified under State law or laws to vote in any election, apply any standard, practice, or procedure different from the standards, practices, or procedures applied under such law or laws to other individuals within the same county, parish, or similar political subdivision who have been found by State officials to be qualified to vote;"],[1,"(B) deny the right of any individual to vote in any election because of an error or omission on any record or paper relating to any application, registration, or other act requisite to voting, if such error or omission is not material in determining whether such individual is qualified under State law to vote in such election; or"],[1,"(C) employ any literacy test as a qualification for voting in any election unless (i) such test is administered to each individual and is conducted wholly in writing, and (ii) a certified copy of the test and of the answers given by the individual is furnished to him within twenty-five days of the submission of his request made within the period of time during which records and papers are required to be retained and preserved pursuant to title III of the Civil Rights Act of 1960 [52 U.S.C. 20701 et seq.]: Provided, however, That the Attorney General may enter into agreements with appropriate State or local authorities that preparation, conduct, and maintenance of such tests in accordance with the provisions of applicable State or local law, including such special provisions as are necessary in the preparation, conduct, and maintenance of such tests for persons who are blind or otherwise physically handicapped, meet the purposes of this subparagraph and constitute compliance therewith."],[0,"(3) For purposes of this subsection—"],[1,"(A) the term \"vote\" shall have the same meaning as in subsection (e) of this section;"],[1,"(B) the phrase \"literacy test\" includes any test of the ability to read, write, understand, or interpret any matter."],[0,"(b) Intimidation, threats, or coercion"],[0,"No person, whether acting under color of law or otherwise, shall intimidate, threaten, coerce, or attempt to intimidate, threaten, or coerce any other person for the purpose of interfering with the right of such other person to vote or to vote as he may choose, or of causing such other person to vote for, or not to vote for, any candidate for the office of President, Vice President, presidential elector, Member of the Senate, or Member of the House of Representatives, Delegates or Commissioners from the Territories or possessions, at any general, special, or primary election held solely or in part for the purpose of selecting or electing any such candidate."],[0,"(c) Preventive relief; injunction; rebuttable literacy presumption; liability of United States for costs; State as party defendant"],[0,"Whenever any person has engaged or there are reasonable grounds to believe that any person is about to engage in any act or practice which would deprive any other person of any right or privilege secured by subsection (a) or (b), the Attorney General may institute for the United States, or in the name of the United States, a civil action or other proper proceeding for preventive relief, including an application for a permanent or temporary injunction, restraining order, or other order. If in any such proceeding literacy is a relevant fact there shall be a rebuttable presumption that any person who has not been adjudged an incompetent and who has completed the sixth grade in a public school in, or a private school accredited by, any State or territory, the District of Columbia, or the Commonwealth of Puerto Rico where instruction is carried on predominantly in the English language, possesses sufficient literacy, comprehension, and intelligence to vote in any election. In any proceeding hereunder the United States shall be liable for costs the same as a private person. Whenever, in a proceeding instituted under this subsection any official of a State or subdivision thereof is alleged to have committed any act or practice constituting a deprivation of any right or privilege secured by subsection (a), the act or practice shall also be deemed that of the State and the State may be joined as a party defendant and, if, prior to the institution of such proceeding, such official has resigned or has been relieved of his office and no successor has assumed such office, the proceeding may be instituted against the State."],[0,"(d) Jurisdiction; exhaustion of other remedies"],[0,"The district courts of the United States shall have jurisdiction of proceedings instituted pursuant to this section and shall exercise the same without regard to whether the party aggrieved shall have exhausted any administrative or other remedies that may be provided by law."],[0,"(e) Order qualifying person to vote; application; hearing; voting referees; transmittal of report and order; certificate of qualification; definitions"],[0,"In any proceeding instituted pursuant to subsection (c) in the event the court finds that any person has been deprived on account of race or color of any right or privilege secured by subsection (a), the court shall upon request of the Attorney General and after each party has been given notice and the opportunity to be heard make a finding whether such deprivation was or is pursuant to a pattern or practice. If the court finds such pattern or practice, any person of such race or color resident within the affected area shall, for one year and thereafter until the court subsequently finds that such pattern or practice has ceased, be entitled, upon his application therefor, to an order declaring him qualified to vote, upon proof that at any election or elections (1) he is qualified under State law to vote, and (2) he has since such finding by the court been (a) deprived of or denied under color of law the opportunity to register to vote or otherwise to qualify to vote, or (b) found not qualified to vote by any person acting under color of law. Such order shall be effective as to any election held within the longest period for which such applicant could have been registered or otherwise qualified under State law at which the applicant's qualifications would under State law entitle him to vote."],[0,"Notwithstanding any inconsistent provision of State law or the action of any State officer or court, an applicant so declared qualified to vote shall be permitted to vote in any such election. The Attorney General shall cause to be transmitted certified copies of such order to the appropriate election officers. The refusal by any such officer with notice of such order to permit any person so declared qualified to vote to vote at an appropriate election shall constitute contempt of court."],[0,"An application for an order pursuant to this subsection shall be heard within ten days, and the execution of any order disposing of such application shall not be stayed if the effect of such stay would be to delay the effectiveness of the order beyond the date of any election at which the applicant would otherwise be enabled to vote."],[0,"The court may appoint one or more persons who are qualified voters in the judicial district, to be known as voting referees, who shall subscribe to the oath of office required by section 3331 of title 5, to serve for such period as the court shall determine, to receive such applications and to take evidence and report to the court findings as to whether or not at any election or elections (1) any such applicant is qualified under State law to vote, and (2) he has since the finding by the court heretofore specified been (a) deprived of or denied under color of law the opportunity to register to vote or otherwise to qualify to vote, or (b) found not qualified to vote by any person acting under color of law. In a proceeding before a voting referee, the applicant shall be heard ex parte at such times and places as the court shall direct. His statement under oath shall be prima facie evidence as to his age, residence, and his prior efforts to register or otherwise qualify to vote. Where proof of literacy or an understanding of other subjects is required by valid provisions of State law, the answer of the applicant, if written, shall be included in such report to the court; if oral, it shall be taken down stenographically and a transcription included in such report to the court."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10101?type=usc&year=mostrecent&link-type=html"},"by":{"2":"55"},"q":[{"src":"brief","b":2,"text":"includes all action necessary to make a vote effective.","cite":"52 U.S.C. § 10101(e)"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"No person acting under color of law shall . . . in determining whether any individual is qualifed under State law or laws to vote in any election, apply any standard, practice, or procedure different from the standards, practices, or procedures applied under such law or laws to other individuals within the same county, parish, or similar political subdivision who have been found by State offcials to be qualifed to vote.","cite":"52 U. S. C. § 10101(a)(2)(A)"}]},{"t":"usc","label":"52 U.S.C. § 10304","url":"https://www.law.cornell.edu/uscode/text/52/10304","subs":["(a)","(b)"],"stext":{"head":"§10304. Alteration of voting qualifications; procedure and appeal; purpose or effect of diminishing the ability of citizens to elect their preferred candidates","paras":[[0,"(a) Whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the first sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1964, or whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the second sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1968, or whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the third sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1972, such State or subdivision may institute an action in the United States District Court for the District of Columbia for a declaratory judgment that such qualification, prerequisite, standard, practice, or procedure neither has the purpose nor will have the effect of denying or abridging the right to vote on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, and unless and until the court enters such judgment no person shall be denied the right to vote for failure to comply with such qualification, prerequisite, standard, practice, or procedure: Provided, That such qualification, prerequisite, standard, practice, or procedure may be enforced without such proceeding if the qualification, prerequisite, standard, practice, or procedure has been submitted by the chief legal officer or other appropriate official of such State or subdivision to the Attorney General and the Attorney General has not interposed an objection within sixty days after such submission, or upon good cause shown, to facilitate an expedited approval within sixty days after such submission, the Attorney General has affirmatively indicated that such objection will not be made. Neither an affirmative indication by the Attorney General that no objection will be made, nor the Attorney General's failure to object, nor a declaratory judgment entered under this section shall bar a subsequent action to enjoin enforcement of such qualification, prerequisite, standard, practice, or procedure. In the event the Attorney General affirmatively indicates that no objection will be made within the sixty-day period following receipt of a submission, the Attorney General may reserve the right to reexamine the submission if additional information comes to his attention during the remainder of the sixty-day period which would otherwise require objection in accordance with this section. Any action under this section shall be heard and determined by a court of three judges in accordance with the provisions of section 2284 of title 28 and any appeal shall lie to the Supreme Court."],[0,"(b) Any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting that has the purpose of or will have the effect of diminishing the ability of any citizens of the United States on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, to elect their preferred candidates of choice denies or abridges the right to vote within the meaning of subsection (a) of this section."],[0,"(c) The term \"purpose\" in subsections (a) and (b) of this section shall include any discriminatory purpose."],[0,"(d) The purpose of subsection (b) of this section is to protect the ability of such citizens to elect their preferred candidates of choice."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10304?type=usc&year=mostrecent&link-type=html"},"by":{"2":"55","3":"30"}},{"t":"case","label":"Evenwel v. Abbott","cite":"578 U.S. 54","y":2016,"id":"2015/14-940","sc":1,"by":{"3":"14"}},{"t":"case","label":"Katzenbach v. Morgan","cite":"384 U.S. 641","y":1966,"id":"1965/847","sc":1,"by":{"3":"32"},"q":[{"src":"brief","b":3,"text":"abrogating only those state laws that the judicial branch [is] prepared to adjudge unconstitutional.","cite":"384 U.S. 641, 649"}]},{"t":"case","label":"Lopez v. Monterey County","cite":"525 U.S. 266","y":1999,"id":"1998/97-1396","sc":1,"by":{"3":"32"},"q":[{"src":"brief","b":3,"text":"[L]egislation which deters or remedies constitutional violations can fall within the sweep of Congress’ enforcement power even if * * * it prohibits conduct which is not itself unconstitutional.","cite":"525 U.S. 266, 282-283"}]},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"by":{"3":"20"},"q":[{"src":"brief","b":3,"text":"in the area of statutory interpretation,","cite":"491 U.S. 164, 172"}]},{"t":"case","label":"Presley v. Etowah County Comm’n","cite":"502 U.S. 491","y":1992,"id":"1991/90-711","sc":1,"by":{"3":"30"}},{"t":"case","label":"Yick Wo v. Hopkins","cite":"118 U.S. 356","y":1886,"id":"1850-1900/118us356","sc":1,"by":{"3":"2"}},{"t":"usc","label":"52 U.S.C. § 10308","url":"https://www.law.cornell.edu/uscode/text/52/10308","subs":["(d)"],"by":{"3":"1"}},{"t":"case","label":"Adarand Constructors, Inc. v. Pena","cite":"515 U.S. 200","y":1995,"id":"1994/93-1841","sc":1,"by":{"4":"32"},"q":[{"src":"brief","b":4,"text":"[B]ut under our Constitution there can be no such thing as either a creditor or a debtor race.","cite":"515 U.S. 200, 239"},{"src":"argument","who":"Mr. Lacour","text":"Well, this Court has specified -- and I don't take the plaintiffs to be arguing that Shaw should be overruled or that Adarand should be overruled."}]},{"t":"case","label":"Banerian v. Benson","cite":"2022 WL 676001","y":2022,"court":"W.D. Mich. Mar. 4","by":{"4":"21, 22"},"q":[{"src":"brief","b":4,"text":"involve legislative judgments, not judicial ones.","cite":"2022 WL 676001"}]},{"t":"case","label":"Brentwood Acad. v. Tenn. Secondary Sch. Athletic Ass’n","cite":"531 U.S. 288","y":2001,"id":"2000/99-901","sc":1,"by":{"4":"38"}},{"t":"case","label":"Chamber of Com. of U.S. v. Whiting","cite":"563 U.S. 582","y":2011,"id":"2010/09-115","sc":1,"by":{"4":"9"}},{"t":"case","label":"City of Richmond v. J.A. Croson Co.","cite":"488 U.S. 469","y":1989,"id":"1988/87-998","sc":1,"by":{"4":"40"},"q":[{"src":"brief","b":4,"text":"‘[r]elief’ for such an ill-defined wrong could extend until the percentage of [majority-minority districts] mirrored the percentage of minorities in the population as a whole.","cite":"488 U.S. 469, 498"}]},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"by":{"4":"6"},"q":[{"src":"brief","b":4,"text":"muddy the meaning of clear statutory language,","cite":"139 S. Ct. 2356, 2364"}]},{"t":"case","label":"Gratz v. Bollinger","cite":"539 U.S. 244","y":2003,"id":"2002/02-516","sc":1,"by":{"4":"31"}},{"t":"case","label":"Hays v. Louisiana","cite":"936 F. Supp. 360","y":1996,"court":"W.D. La.","url":"https://www.courtlistener.com/c/F.%20Supp./936/360/","by":{"4":"26, 27"}},{"t":"case","label":"Jenkins v. Red Clay Consol. Sch. Dist. Bd. of Educ.","cite":"4 F.3d 1103","y":1993,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/4/1103/","by":{"4":"15"}},{"t":"case","label":"Kirksey v. Bd. of Sup’rs of Hinds Cnty.","cite":"554 F.2d 139","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/554/139/","by":{"4":"7"}},{"t":"case","label":"McCulloch v. Maryland","cite":"4 Wheat. 316","y":1819,"url":"https://www.courtlistener.com/c/Wheat./4/316/","by":{"4":"41"}},{"t":"case","label":"NAACP v. City of Niagara Falls","cite":"65 F.3d 1002","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/65/1002/","by":{"4":"15"}},{"t":"case","label":"Parents Involved in Cmty. Sch. v. Seattle Sch. Dist. No. 1","cite":"551 U.S. 701","y":2007,"id":"2006/05-915","sc":1,"by":{"4":"13, 40"},"q":[{"src":"brief","b":4,"text":"[a]s the districts’ demographics shift, so too will [Plaintiffs’] definition of [vote dilution].","cite":"551 U.S. 701, 731"},{"src":"brief","b":4,"text":"it would leave our equal protection jurisprudence at the mercy of elected government officials evaluating the evanescent views of a handful of social scientists.","cite":"551 U.S. at 766"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"would effectively assure that race will always be relevant in [redistricting], and that the ultimate goal of eliminating entirely from governmental decisionmaking such irrelevant factors as a human being's race will never be achieved.","cite":"551 U. S., at 730"}]},{"t":"case","label":"Robinson v. Ardoin","cite":"2022 WL 2012389","y":2022,"court":"M.D. La. June 6","by":{"4":"27"}},{"t":"case","label":"Tennessee v. Lane","cite":"541 U.S. 509","y":2004,"id":"2003/02-1667","sc":1,"by":{"4":"41"},"q":[{"src":"brief","b":4,"text":"by a relevant history and pattern of constitutional violations.","cite":"541 U.S. 509, 521"},{"src":"argument","who":"Mr. Lacour","text":"And as Bill Cooper, the plaintiffs' expert, the Caster plaintiffs' expert explained, that's because the Tennessee River runs east to west up there."}]},{"t":"const","label":"Amendment XV, Section 1","clauses":[["fifteenth-amendment","Fifteenth Amendment"]],"text":"The right of citizens of the United States to vote shall not be denied or abridged by the United States or by any State on account of race, color, or previous condition of servitude--","by":{"4":"37"}}]};